186	function rotatePoint(p, axis, degrees, origin) {
187	  if (!degrees) return p;
188	  const a = (degrees * Math.PI) / 180;
189	  const c = Math.cos(a), s = Math.sin(a);
190	  let [x, y, z] = p;
191	  const [ox, oy, oz] = origin;
192	  x -= ox; y -= oy; z -= oz;
193	  if (axis === 'x') { const ny = y * c - z * s; const nz = y * s + z * c; y = ny; z = nz; }
194	  else if (axis === 'y') { const nx = x * c + z * s; const nz = -x * s + z * c; x = nx; z = nz; }
195	  else { const nx = x * c - y * s; const ny = x * s + y * c; x = nx; y = ny; }
196	  return [x + ox, y + oy, z + oz];
197	}
