201	  switch (dir) {
202	    case 'down': return [x1, 16 - z2, x2, 16 - z1];
203	    case 'up': return [x1, z1, x2, z2];
204	    case 'north': return [16 - x2, 16 - y2, 16 - x1, 16 - y1];
205	    case 'south': return [x1, 16 - y2, x2, 16 - y1];
206	    case 'west': return [z1, 16 - y2, z2, 16 - y1];
207	    case 'east': return [16 - z2, 16 - y2, 16 - z1, 16 - y1];
208	  }
209	  return [0, 0, 16, 16];
