235	function bakeModel(model, variantRot) {
236	  const quads = [];
237	  for (const el of model.elements) {
238	    const from = el.from.map(Number);
239	    const to = el.to.map(Number);
240	    const elRot = el.rotation;
241	    for (const dir of DIRS) {
242	      const face = el.faces?.[dir];
243	      if (!face || !face.texture) continue;
244	      let corners = faceCorners(dir, from, to);
245	      if (elRot) {
246	        corners = corners.map(c => rotatePoint(c, elRot.axis, Number(elRot.angle) || 0, elRot.origin || [8, 8, 8]));
247	      }
248	      if (variantRot) {
249	        corners = corners.map(c => {
250	          let p = rotatePoint(c, 'y', variantRot.y || 0, [8, 8, 8]);
251	          p = rotatePoint(p, 'x', variantRot.x || 0, [8, 8, 8]);
252	          return p;
253	        });
254	      }
255	      const uv = Array.isArray(face.uv) ? face.uv.map(Number) : autoUV(dir, from, to);
256	      const uvOrdered = rotateUv(uv, Number(face.rotation) || 0);
257	      const tex = resolveTexture(face.texture, model.textures);
258	      quads.push({
259	        p: corners.flat().map(v => Math.round((v / 16) * 10000) / 10000),
260	        uv: uvOrdered,
261	        t: tex.key,
262	        tr: tex.tr || undefined,
263	        d: DIR_INDEX[dir],
264	        c: face.cullface ? DIR_INDEX[face.cullface] : -1,
265	        ti: face.tintindex ?? -1,
266	        s: face.shade !== false && el.shade !== false,
267	        ao: model.ao !== false,
268	      });
269	    }
270	  }
271	  return quads;
272	}
