#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Read-only inventory of vanilla 26.2 blockstate/model data for webcraft26.

Usage: python research/inventory.py
Writes: research/blockstate-inventory.json (machine summary)
        research/_inventory_dump.txt        (human-readable console log)
Nothing outside research/ is touched.
"""
import json, os, re, sys, glob, itertools
from collections import Counter, defaultdict, OrderedDict

ROOT = "G:/ck-web26/vanilla/assets/minecraft"
BS_DIR = os.path.join(ROOT, "blockstates")
MB_DIR = os.path.join(ROOT, "models", "block")
MI_DIR = os.path.join(ROOT, "models", "item")
TX_DIR = os.path.join(ROOT, "textures")
PROJ = "C:/Users/zht/Documents/Qoder/2026-11-01/4194ac07/webcraft26"
SRCV = "G:/ck-web26/src-vanilla"

OUT_DIR = os.path.dirname(os.path.abspath(__file__))
log_lines = []


def log(*a):
    s = " ".join(str(x) for x in a)
    log_lines.append(s)
    print(s)


def load_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


# ---------------------------------------------------------------- utilities
def split_model_ref(ref):
    """minecraft:block/foo -> ('block','foo'); block/foo -> same."""
    r = re.sub(r"^minecraft:", "", ref)
