def parse_variant_key(key, fname):
    """Return list of (prop, value) preserving file order, plus flags."""
    if key == "":
        return [], True
    parts = key.split(",")
    out = []
    for p in parts:
        if "=" not in p:
            weird_key_parts.append((fname, key, p))
            continue
        k, v = p.split("=", 1)
        out.append((k, v))
    names = [k for k, _ in out]
    if names != sorted(names):
        nonalpha_keys.append((fname, key))
    for k, v in out:
        if "|" in v or "&" in v or "!" in v:
            keys_with_or.append((fname, key, v))
    return out, False


def walk_condition(cond, depth, stats, fname):
    """Accumulate operator/leaf statistics for a multipart condition node."""
    stats["max_depth"] = max(stats["max_depth"], depth)
    stats["nodes"] += 1
    if isinstance(cond, dict):
        for k, v in cond.items():
            if k in ("OR", "AND", "INVERT"):
                stats["ops"][k] += 1
                if k in ("OR", "AND"):
                    if isinstance(v, list):
                        stats["op_list_len"][k].append(len(v))
                        for sub in v:
                            walk_condition(sub, depth + 1, stats, fname)
                    else:
                        stats["bad"].append((fname, k, "not-list"))
                else:
                    walk_condition(v, depth + 1, stats, fname)
            else:
                # property leaf
                stats["props"].append(k)
                if isinstance(v, list):
                    stats["leaf_list"] += 1
                    for item in v:
                        stats["leaf_value_types"][type(item).__name__] += 1
                elif isinstance(v, dict):
                    stats["bad"].append((fname, k, "dict-value"))
                else:
                    stats["leaf_value_types"][type(v).__name__] += 1
    elif isinstance(cond, list):
        for sub in cond:
            walk_condition(sub, depth + 1, stats, fname)
    else:
        stats["bad"].append((fname, "cond", type(cond).__name__))


def collect_apply(apply, fname, stats):
    items = apply if isinstance(apply, list) else [apply]
    if isinstance(apply, list):
        stats["apply_lists"].append(len(items))
    for it in items:
        if not isinstance(it, dict):
            stats["bad_apply"].append((fname, str(it)[:40]))
            continue
        if "model" not in it:
            stats["bad_apply"].append((fname, "no-model"))
        else:
            m = it["model"]
            model_refs_used.add(m)
            model_ref_prefixes[split_model_ref(m).split("/")[0]] += 1
            if not os.path.exists(os.path.join(ROOT, "models", split_model_ref(m) + ".json")):
                missing_models_bs.append((fname, m))
        for k in it:
            stats["apply_fields"][k] += 1
        if "uvlock" in it:
            stats["uvlock_files"] += 1
        if "weight" in it:
            stats["weight_values"][it["weight"]] += 1


