def resolve_textures(model_key, own_tex=None, chain_cache={}):
    """Return dict of texture-alias -> literal path, walking parents."""
    out = {}
    cur = model_key
    seen = set()
    defs = []
    while cur and cur not in seen:
        seen.add(cur)
        m = models.get(cur)
        if not m:
            break
        defs.append(m.get("textures") or {})
        cur = get_parent_key(m)
    for d in reversed(defs):
        out.update(d)
    return out


def deref(val, texmap, depth=0):
    if depth > 20:
        return None, "loop"
    if isinstance(val, dict):
        return deref(val.get("sprite"), texmap, depth + 1)
    if not isinstance(val, str):
        return None, "nonstr"
    if val.startswith("#"):
        k = val[1:]
        if k not in texmap:
            return None, "missing-var:" + k
        return deref(texmap[k], texmap, depth + 1)
    return re.sub(r"^minecraft:", "", val), None


