def collect_from_model(mkey, visited):
    """walk model + parents, return (set of png paths, list of errors, set of element-face sprites)."""
    if mkey in visited:
        return set(), [], set()
    visited.add(mkey)
    texmap = resolve_textures(mkey)
    pngs = set()
    errs = []
    sprites = set()
    # own elements only (vanilla does not inherit elements across parents, but the
    # project bakes them; check both)
    els = models.get(mkey, {}).get("elements")
    if els is None:
        # element inheritance: vanilla ModelBase#getElementsFromJson does NOT traverse
        # parents; but record for transparency
        cur = get_parent_key(models.get(mkey, {}))
        while cur and cur not in visited:
            if cur in models and models[cur].get("elements") is not None:
                break
            cur = get_parent_key(models.get(cur, {})) if cur in models else None
        els = None
    if isinstance(els, list):
        for el in els:
            for d, f in (el.get("faces") or {}).items() if isinstance(el, dict) else []:
                t = f.get("texture") if isinstance(f, dict) else None
                if t is None:
                    continue
                path, err = deref(t, texmap)
                if err:
                    errs.append((mkey, d, err))
                else:
                    sprites.add(path)
    # named textures that are literal paths (used by parents like cube_all)
    for k, v in texmap.items():
        p, e = deref(v, texmap)
        if p and ("/" in p):
            pngs.add(p)
    return pngs, errs, sprites


